/**
 * 官方 8 点环形点阵跑马灯坐标数组
 */
const DSH_MATRIX_COORDS = [
  [0, 0], [4, 0], [8, 0],
  [8, 4],
  [8, 8], [4, 8], [0, 8],
  [0, 4]
];

/**
 * 官方原版会话状态点阵跑马灯渲染器 (StateMatrix)
 * @param size - 视图尺寸像素
 * @param className - 附加类名
 * @param phaseBaseMs - 可选绝对相位基准（如 performance.now()）。
 *   传入后每个 cell 的负 animation-delay 以该时刻折算，使任何时刻重建的矩阵
 *   相位都等于 (t - (idx-8)*125) mod 1000 —— 与创建时刻无关，重建不跳相。
 *   缺省 0 = 旧行为（各自以创建时刻为相位零点）。
 */
function renderStateMatrix(size, className, phaseBaseMs) {
  const sz = size || 10;
  const base = Number.isFinite(Number(phaseBaseMs)) ? (Number(phaseBaseMs) % 1000) : 0;
  const rects = DSH_MATRIX_COORDS.map(([x, y], idx) => {
    const delay = (idx - DSH_MATRIX_COORDS.length) * 125 - base;
    return '<rect class="dsh-matrix-cell" x="' + x + '" y="' + y + '" width="2" height="2" style="animation-delay:' + delay + 'ms"/>';
  }).join('');

  return '<svg class="dsh-state-matrix' + (className ? ' ' + className : '') + '" data-state="ongoing" width="' + sz + '" height="' + sz + '" viewBox="0 0 10 10" shape-rendering="crispEdges" aria-hidden="true">' + rects + '</svg>';
}

/**
 * 官方矩形字符胶囊渲染器 (BrandBadge)
 */
function renderBrandBadge(text, className) {
  const label = (text || 'HARNESS').toUpperCase();
  return '<span class="dsh-brand-badge' + (className ? ' ' + className : '') + '">' + label + '</span>';
}

/**
 * 通用图标与组件渲染器
 */
function renderDSHIcon(iconName, size, className) {
  if (iconName === 'StateMatrix' || iconName === 'Matrix') {
    return renderStateMatrix(size, className);
  }
  if (iconName === 'BrandBadge' || iconName === 'HarnessBadge') {
    return renderBrandBadge(size || 'HARNESS', className);
  }

  const asset = DSH_ASSETS[iconName];
  if (!asset) return '';
  const w = size || (asset.viewBox.startsWith('0 0 16') ? 16 : (asset.viewBox.startsWith('0 0 14') ? 14 : 20));
  const h = asset.aspectRatio ? Math.round((w / asset.aspectRatio) * 100) / 100 : w;
  
  const pathsHTML = asset.elements.map(el => {
    const rules = el.evenodd ? ' fill-rule="evenodd" clip-rule="evenodd"' : '';
    return '<path d="' + el.d + '" fill="currentColor"' + rules + '/>';
  }).join('');
  
  return '<svg width="' + w + '" height="' + h + '" viewBox="' + asset.viewBox + '" fill="none"' + (className ? ' class="' + className + '"' : '') + ' aria-hidden="true">' + pathsHTML + '</svg>';
}

function injectDSHAssets() {
  document.querySelectorAll('[data-dsh-icon]').forEach(el => {
    const name = el.getAttribute('data-dsh-icon');
    const size = parseInt(el.getAttribute('data-size') || '', 10) || null;
    const text = el.getAttribute('data-text') || null;
    const cls = el.getAttribute('class') || '';
    
    if (name === 'BrandBadge') {
      el.outerHTML = renderBrandBadge(text || 'HARNESS', cls);
    } else {
      const svgHTML = renderDSHIcon(name, size, cls);
      if (svgHTML) {
        el.outerHTML = svgHTML;
      }
    }
  });
}

// 自动注入官方状态矩阵与品牌矩形胶囊样式
(function() {
  if (typeof document === 'undefined') return;
  const style = document.createElement('style');
  style.textContent = `
    .dsh-state-matrix {
      flex: none;
      color: var(--dsh-mgr-sem-working, var(--dsw-static-deepseek-450, #5686fe));
      display: inline-block;
      vertical-align: middle;
    }
    .dsh-matrix-cell {
      fill: currentColor;
      opacity: 0.15;
      animation: dsh-state-dot-chase 1s infinite;
    }
    @keyframes dsh-state-dot-chase {
      0%, 12.4% { opacity: 1; }
      12.5%, 24.9% { opacity: 0.6; }
      25%, 37.4% { opacity: 0.35; }
      37.5%, 100% { opacity: 0.15; }
    }

    /* 官方原厂 Brand Badge 矩形胶囊 */
    .dsh-brand-badge {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      height: 15px;
      padding: 0 4px;
      border-radius: 3px;
      background: var(--dsw-alias-button-primary-fill, #0f1115);
      color: var(--dsw-alias-label-primary-foreground, #ffffff);
      font-family: var(--dsw-font-family, sans-serif);
      font-size: 9.5px;
      font-weight: 700;
      letter-spacing: 0.5px;
      line-height: 1;
      text-transform: uppercase;
      vertical-align: middle;
      user-select: none;
      box-shadow: 0 1px 2px rgba(0,0,0,0.12);
    }
    [data-theme="dark"] .dsh-brand-badge,
    [data-ds-dark-theme] .dsh-brand-badge {
      background: #f1f3f5;
      color: #0f1115;
    }
  `;
  document.head.appendChild(style);
})();

if (typeof window !== 'undefined') {
  window.DSH_ASSETS = DSH_ASSETS;
  window.renderDSHIcon = renderDSHIcon;
  window.renderStateMatrix = renderStateMatrix;
  window.renderBrandBadge = renderBrandBadge;
  window.injectDSHAssets = injectDSHAssets;
}
